def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_c = sum(1 for a in opp if a == 'C')
    total_d = n - total_c

    if total_c == 0:
        return 'D'

    # Opponent has never defected: after a brief mutual-cooperation sample,
    # switch to exploitation. This targets unconditional/all-cooperative types
    # while limiting early damage against simple retaliators.
    if total_d == 0 and n >= 12:
        return 'D'

    last_my, last_opp = me[-1], opp[-1]

    W = 10 if n > 10 else n
    recent_opp = opp[n - W:]
    rc = sum(1 for a in recent_opp if a == 'C')
    rd = W - rc

    # Opponent D-streak length.
    sd = 0
    for a in reversed(opp):
        if a == 'D':
            sd += 1
        else:
            break

    # Persistent defection should usually be answered with defection.
    if sd >= 7 and last_opp == 'D':
        return 'D'

    # Very recent block where opponent is cooperative and has allowed a D by us.
    R8 = 8 if n > 8 else n
    c8 = 0
    soft8 = 0
    hard8 = 0
    for i in range(n - R8, n):
        if opp[i] == 'C':
            c8 += 1
        if me[i] == 'D':
            if opp[i] == 'C':
                soft8 += 1
            else:
                hard8 += 1

    if last_opp == 'C' and soft8 >= 1 and hard8 == 0 and c8 >= 7:
        return 'D'

    E = 15 if n > 15 else n
    soft = 0
    hard = 0
    lagsoft = 0
    laghard = 0

    # Same-round D responses: (our D, opponent C/D).
    for i in range(n - E, n):
        if me[i] == 'D':
            if opp[i] == 'C':
                soft += 1
            else:
                hard += 1

    # Lagged responses: our previous D predicts opponent's current action.
    start = max(0, n - 1 - E)
    for i in range(start, n - 1):
        if me[i] == 'D':
            if opp[i + 1] == 'C':
                lagsoft += 1
            else:
                laghard += 1

    # Transition counts from our previous action to opponent's next action.
    rc_lag = 0
    rt_lag = 0
    rd_lag = 0
    dt_lag = 0
    start = max(0, n - 1 - 15)
    for i in range(start, n - 1):
        if me[i] == 'C':
            rt_lag += 1
            if opp[i + 1] == 'C':
                rc_lag += 1
        else:
            dt_lag += 1
            if opp[i + 1] == 'C':
                rd_lag += 1

    recent_ratio = rc / float(W)

    # Explicit exploit mode: defections by us are not punished more than the
    # opponent's own general defect frequency.
    if soft + hard > 0:
        hard_ratio = hard / float(soft + hard)
        baseline = rd / float(W)

        if soft + 0.5 * lagsoft >= 2 and hard_ratio <= max(baseline, 0.25) and rc >= rd:
            return 'D'
        if soft > hard and hard_ratio <= baseline + 0.12 and rc >= 0.55 * W:
            return 'D'

    # Smoothed one-step model:
    #   rC = P(opponent cooperates next | we played C)
    #   rD = P(opponent cooperates next | we played D)
    # Priors assume retaliation unless evidence says otherwise, with a small
    # allowance for generally cooperative opponents.
    prior_c = 0.6 + 0.4 * recent_ratio
    prior_d = 0.1 + 0.6 * recent_ratio

    if hard + laghard > soft + lagsoft:
        prior_d = 0.05
    elif soft + lagsoft > hard + laghard and prior_d < 0.55:
        prior_d = 0.55

    rC = (rc_lag + 3.0 * prior_c) / (rt_lag + 3.0)
    rD = (rd_lag + 3.0 * prior_d) / (dt_lag + 3.0)
    rC = max(0.0, min(1.0, rC))
    rD = max(0.0, min(1.0, rD))

    # Immediate opponent-Cooperation probability, blended from action-response,
    # last opponent action, and recent cooperation ratio.
    p = rC if last_my == 'C' else rD
    last_c = 1.0 if last_opp == 'C' else 0.0
    p = 0.50 * p + 0.30 * last_c + 0.20 * recent_ratio
    p = max(0.0, min(1.0, p))

    # Two-round "stay" expected scores under the model.
    scoreD = 2.0 + 4.0 * p + 4.0 * rD
    scoreC = 3.0 * p + 3.0 * rC

    if last_opp == 'D':
        if last_my == 'D':
            # Mutual defection: usually try to recover, unless the opponent is
            # a hard defector and the model still favors continued D.
            if rd > rc and scoreD > scoreC and sd >= 3:
                return 'D'
            return 'C'
        else:
            # We cooperated and were defected on.
            # Forgive one isolated defect from a strongly cooperative opponent.
            if sd == 1 and rc >= 9:
                return 'C'
            if sd == 2 and rc >= 8 and hard8 <= 1:
                return 'C'

            # Second round of a deliberate DD -> C recovery sequence.
            if n >= 2 and me[-2] == 'D' and opp[-2] == 'D':
                return 'C'

            # If opponent seems cooperative/retaliatory rather than exploitative,
            # keep trying to reestablish CC.
            if rc >= 8 and sd <= 3 and soft + lagsoft > hard + laghard:
                return 'C'

            if scoreD > scoreC - 0.25:
                return 'D'
            return 'C'

    else:
        # Opponent cooperated last round.
        if last_my == 'D':
            # We just D-ed and they still C-ed: strong exploit signal if recent
            # opponent behavior is mostly C and they did not D back.
            if hard8 == 0 and soft8 >= 1 and rc >= 7:
                return 'D'
            if scoreD > scoreC + 0.5:
                return 'D'
            return 'C'
        else:
            # Mutual cooperation. Use very rare probing when opponent appears
            # non-hostile and has not shown punishment in recent D responses.
            if n % 31 == 0 and rc >= 8 and hard + laghard == 0 and soft + lagsoft == 0:
                if rng.random() < 0.20:
                    return 'D'

            if rng.random() < 0.005 and rc >= 9 and hard + laghard == 0 and soft == 0:
                return 'D'

            # If evidence already says D is safe, model can promote exploitation.
            if scoreD > scoreC + 2.0 and soft + lagsoft >= 2:
                return 'D'

            # Endgame: defect in final few rounds against likely cooperators.
            if n >= 96 and rc >= 7:
                return 'D'

            return 'C'
